/* From Uiverse.io by Lmickk2 - Tags: loading, loader, light&dark */
.__UIV_SCOPE__ .loader {
  display: flex;
  transition: all 0.4s;
}

.__UIV_SCOPE__ .loader div {
  margin-left: 0.8rem;
  background-color: rgb(34, 34, 34);
  box-shadow: inset 2px 2px 10px black;
  border-radius: 100%;
  height: 1rem;
  width: 1rem;
}

.__UIV_SCOPE__ .box-load1 {
  animation: brighten 1.2s infinite;
}

.__UIV_SCOPE__ .box-load2 {
  animation: brighten 1.2s infinite;
  animation-delay: .2s;
}

.__UIV_SCOPE__ .box-load3 {
  animation: brighten 1.2s infinite;
  animation-delay: .4s;
}

@keyframes brighten {
  100% {
    background-color: rgb(165, 165, 165);
    box-shadow: none;
  }
}
